def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])

    names = set(packages) | set(roots)
    for rows in packages.values():
        for row in rows:
            for dep in row.get('deps', []):
                names.add(dep['name'])
    ordered_names = sorted(names)
    best_vector = None
    best_versions = None

    requirements = {name: tuple(bounds) for name, bounds in roots.items()}
    if any(low > high for low, high in requirements.values()):
        return {'error': 'unsatisfiable'}

    def search(req, chosen, graph):
        nonlocal best_vector, best_versions

        if all(name in chosen for name in req):
            vector = tuple(chosen.get(name, -1) for name in ordered_names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(chosen)
            return

        name = min(n for n in req if n not in chosen)
        low, high = req[name]
        rows = choose(packages.get(name, []), low, high,
                      blocked.get(name, []), pins.get(name))

        for row in rows:
            version = row['version']
            next_req = dict(req)
            next_chosen = dict(chosen)
            next_graph = {n: list(edges) for n, edges in graph.items()}
            next_chosen[name] = version
            next_graph.setdefault(name, [])
            valid = True

