                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                child = dep['name']
                dep_low, dep_high = dep['min'], dep['max']
                if child in next_req:
                    old_low, old_high = next_req[child]
                    dep_low = max(dep_low, old_low)
                    dep_high = min(dep_high, old_high)
                if dep_low > dep_high:
                    valid = False
                    break
                next_req[child] = (dep_low, dep_high)
                if child in next_chosen and not (dep_low <= next_chosen[child] <= dep_high):
                    valid = False
                    break
                if _has_path(next_graph, child, name):
                    valid = False
                    break
                next_graph[name].append(child)

            if valid:
                search(next_req, next_chosen, next_graph)

    search(requirements, {}, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}


def _has_path(graph, start, target):
    pending = [start]
    visited = set()
    while pending:
        node = pending.pop()
        if node == target:
            return True
        if node in visited:
            continue
        visited.add(node)
        pending.extend(graph.get(node, []))
    return False
